import re
import matplotlib.pyplot as plt
import seaborn as sns
import pandas as pd

# Parse results.out generated by Go
data = []
try:
    with open('results.out', 'r') as f:
        for line in f:
            if 'BenchmarkGol/' in line:
                parts = line.split()
                if len(parts) >= 3:
                    name = parts[0]
                    # Extract worker count from name like BenchmarkGol/1_workers-12
                    match = re.search(r'/(\d+)_workers', name)
                    if match:
                        workers = int(match.group(1))
                        ns_op = float(parts[2])  # time in nanoseconds per op
                        seconds = ns_op / 1e9    # convert to seconds
                        data.append({'Workers': str(workers), 'Workers_int': workers, 'Time': seconds})
except FileNotFoundError:
    print("Error: results.out not found. Make sure you ran the benchmark command first!")
    exit(1)

# Create DataFrame and compute average time for each worker count
df = pd.DataFrame(data)
df_grouped = df.groupby(['Workers', 'Workers_int'], as_index=False)['Time'].mean()
df_grouped = df_grouped.sort_values('Workers_int')

# Set up the plot style matching your reference image
sns.set_theme(style="ticks")
plt.figure(figsize=(7, 5))

# Draw the bar plot using seaborn palette
ax = sns.barplot(x='Workers', y='Time', data=df_grouped, palette='deep')

# Customize labels and axes to match the required format
plt.xlabel('Worker threads used', fontsize=11)
plt.ylabel('Time taken (s)', fontsize=11)
sns.despine()

# Save and show the plot
plt.tight_layout()
plt.savefig('benchmark_graph.png', dpi=300)
print("Graph successfully generated and saved as 'benchmark_graph.png'!")
plt.show()